{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-07-30 17:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be your doctor during this stay. Can you tell me what brought you in today?"
    },
    {
      "turn_number": 2,
      "time": "2156-07-30 17:16:00",
      "speaker": "Patient",
      "text": "Hi. I’ve been having a lot of diarrhea—up to eight times today—and I can’t keep anything down, not even my tube feeds. My blood sugar was really high too."
    },
    {
      "turn_number": 3,
      "time": "2156-07-30 17:17:00",
      "speaker": "Doctor",
      "text": "I see. And any nausea or vomiting?"
    },
    {
      "turn_number": 4,
      "time": "2156-07-30 17:18:00",
      "speaker": "Patient",
      "text": "Yes, started yesterday. I also feel this weird 'electricity' all over my body for the past few days."
    },
    {
      "turn_number": 5,
      "time": "2156-07-30 17:19:00",
      "speaker": "Doctor",
      "text": "That’s important. We’ll check your electrolytes. Did you eat anything different recently?"
    },
    {
      "turn_number": 6,
      "time": "2156-07-30 17:20:00",
      "speaker": "Patient",
      "text": "I had seafood in ___ a few days ago. I think that might have triggered this."
    },
    {
      "turn_number": 7,
      "time": "2156-07-30 17:21:00",
      "speaker": "Doctor",
      "text": "Okay. We’ll test your stool to rule out infections. Your blood sugar was 497 in the ER, so we’ve already given you insulin and fluids."
    },
    {
      "turn_number": 8,
      "time": "2156-07-30 17:22:00",
      "speaker": "Patient",
      "text": "Thank you. My abdominal pain is about the same as usual, not worse. But I just can’t tolerate food or feeds."
    },
    {
      "turn_number": 9,
      "time": "2156-07-30 17:23:00",
      "speaker": "Doctor",
      "text": "We’ll keep you on bowel rest for now and give IV fluids. We’ll start tube feeds slowly once your nausea improves."
    },
    {
      "turn_number": 10,
      "time": "2156-07-30 17:24:00",
      "speaker": "Patient",
      "text": "Okay. And my 'electric' feeling—is that from high sugar?"
    },
    {
      "turn_number": 11,
      "time": "2156-07-30 17:25:00",
      "speaker": "Doctor",
      "text": "Possibly. It could be neuropathy from your diabetes. We’ll monitor it and adjust your insulin."
    },
    {
      "turn_number": 12,
      "time": "2156-08-01 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your stool tests came back negative for C. diff, Salmonella, Shigella, and Campylobacter."
    },
    {
      "turn_number": 13,
      "time": "2156-08-01 09:01:00",
      "speaker": "Patient",
      "text": "So it’s not an infection?"
    },
    {
      "turn_number": 14,
      "time": "2156-08-01 09:02:00",
      "speaker": "Doctor",
      "text": "Not a bacterial one. Given your history of chronic pancreatitis and gastroparesis, this may be a flare-up related to your pancreas condition."
    },
    {
      "turn_number": 15,
      "time": "2156-08-01 09:03:00",
      "speaker": "Patient",
      "text": "But I ate seafood—could that still be a factor?"
    },
    {
      "turn_number": 16,
      "time": "2156-08-01 09:04:00",
      "speaker": "Doctor",
      "text": "It might have irritated your system, but it doesn’t look like a foodborne infection. We’ll focus on managing your underlying conditions."
    },
    {
      "turn_number": 17,
      "time": "2156-08-03 10:15:00",
      "speaker": "Doctor",
      "text": "We’re starting your tube feeds at 5 cc/hr. We’ll increase slowly if you tolerate it."
    },
    {
      "turn_number": 18,
      "time": "2156-08-03 10:16:00",
      "speaker": "Patient",
      "text": "I’m nervous—I usually get pain when I start feeds."
    },
    {
      "turn_number": 19,
      "time": "2156-08-03 10:17:00",
      "speaker": "Doctor",
      "text": "We’ll monitor closely. If you have pain, we’ll pause and reassess. You’ll have IV pain meds available."
    },
    {
      "turn_number": 20,
      "time": "2156-08-05 14:00:00",
      "speaker": "Doctor",
      "text": "You’ve had some setbacks with the feeds due to pain, so we had a team meeting to discuss next steps."
    },
    {
      "turn_number": 21,
      "time": "2156-08-05 14:01:00",
      "speaker": "Patient",
      "text": "What did you decide?"
    },
    {
      "turn_number": 22,
      "time": "2156-08-05 14:02:00",
      "speaker": "Doctor",
      "text": "We think your GJ tube might be clogged or not placed optimally. We’re scheduling a tube revision with interventional radiology."
    },
    {
      "turn_number": 23,
      "time": "2156-08-05 14:03:00",
      "speaker": "Patient",
      "text": "Is that a surgery?"
    },
    {
      "turn_number": 24,
      "time": "2156-08-05 14:04:00",
      "speaker": "Doctor",
      "text": "It’s a procedure where they replace the tube using imaging guidance. It’s not open surgery, and you’ll be awake but sedated."
    },
    {
      "turn_number": 25,
      "time": "2156-08-05 14:05:00",
      "speaker": "Patient",
      "text": "Okay, I’ll do it if it might help."
    },
    {
      "turn_number": 26,
      "time": "2156-08-26 13:00:00",
      "speaker": "Doctor",
      "text": "The tube revision was successful. The new tube is in the right place in your jejunum. We’ll wait a few hours and restart feeds."
    },
    {
      "turn_number": 27,
      "time": "2156-08-26 13:01:00",
      "speaker": "Patient",
      "text": "That’s good. I hope this one works better."
    },
    {
      "turn_number": 28,
      "time": "2156-08-27 08:30:00",
      "speaker": "Doctor",
      "text": "You’re tolerating the new tube well. Feeds are at 20 cc/hr with no pain so far."
    },
    {
      "turn_number": 29,
      "time": "2156-08-27 08:31:00",
      "speaker": "Patient",
      "text": "I actually feel a bit better. My 'electric' feeling is less intense."
    },
    {
      "turn_number": 30,
      "time": "2156-08-27 08:32:00",
      "speaker": "Doctor",
      "text": "Great. Your blood sugar is also more stable—around 200. We’ve increased your long-acting insulin to 34 units nightly."
    },
    {
      "turn_number": 31,
      "time": "2156-08-27 08:33:00",
      "speaker": "Patient",
      "text": "Is that safe? I was on 90 units at home."
    },
    {
      "turn_number": 32,
      "time": "2156-08-27 08:34:00",
      "speaker": "Doctor",
      "text": "Yes. Since you weren’t eating, we lowered it to 30 units. Now that you’re feeding again, we’re increasing it gradually to avoid lows."
    },
    {
      "turn_number": 33,
      "time": "2156-08-28 09:00:00",
      "speaker": "Doctor",
      "text": "You had a fall yesterday on your way to the bathroom."
    },
    {
      "turn_number": 34,
      "time": "2156-08-28 09:01:00",
      "speaker": "Patient",
      "text": "Yeah, I slipped. My wrist hurts, and my shoulder feels weak."
    },
    {
      "turn_number": 35,
      "time": "2156-08-28 09:02:00",
      "speaker": "Doctor",
      "text": "X-rays show no fractures in your wrist or shoulder. Ortho thinks it’s a wrist sprain and possible rotator cuff issue."
    },
    {
      "turn_number": 36,
      "time": "2156-08-28 09:03:00",
      "speaker": "Patient",
      "text": "So no break?"
    },
    {
      "turn_number": 37,
      "time": "2156-08-28 09:04:00",
      "speaker": "Doctor",
      "text": "No. We’ve put your wrist in a splint and recommend a sling. Your PCP will order an MRI later."
    },
    {
      "turn_number": 38,
      "time": "2156-08-30 10:00:00",
      "speaker": "Doctor",
      "text": "Your latest labs show your magnesium is low, which might contribute to the 'electric' sensation."
    },
    {
      "turn_number": 39,
      "time": "2156-08-30 10:01:00",
      "speaker": "Patient",
      "text": "Can we fix that?"
    },
    {
      "turn_number": 40,
      "time": "2156-08-30 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, we’re giving you supplements. It should help with the nerve symptoms."
    },
    {
      "turn_number": 41,
      "time": "2156-08-31 11:00:00",
      "speaker": "Doctor",
      "text": "Your urine culture showed mixed flora—likely contamination. No infection."
    },
    {
      "turn_number": 42,
      "time": "2156-08-31 11:01:00",
      "speaker": "Patient",
      "text": "I’ve had some vaginal discharge for months. Should I get checked?"
    },
    {
      "turn_number": 43,
      "time": "2156-08-31 11:02:00",
      "speaker": "Doctor",
      "text": "Yes, but you declined the exam. Please follow up with your PCP after discharge."
    },
    {
      "turn_number": 44,
      "time": "2156-09-01 09:30:00",
      "speaker": "Doctor",
      "text": "We’re planning for discharge soon. Your nutrition is stable—you’ve actually gained weight despite not eating much."
    },
    {
      "turn_number": 45,
      "time": "2156-09-01 09:31:00",
      "speaker": "Patient",
      "text": "I didn’t realize that. I feel like I haven’t eaten in weeks."
    },
    {
      "turn_number": 46,
      "time": "2156-09-01 09:32:00",
      "speaker": "Doctor",
      "text": "But your albumin is normal, so you’re getting enough through the tube. We’re weaning your IV pain meds and switching to oral Dilaudid."
    },
    {
      "turn_number": 47,
      "time": "2156-09-01 09:33:00",
      "speaker": "Patient",
      "text": "I’m okay with that. I don’t want to stay on IV meds forever."
    },
    {
      "turn_number": 48,
      "time": "2156-09-02 10:00:00",
      "speaker": "Doctor",
      "text": "We’ve added some new meds for constipation—senna, docusate, and bisacodyl. Your narcotics cause this."
    },
    {
      "turn_number": 49,
      "time": "2156-09-02 10:01:00",
      "speaker": "Patient",
      "text": "I’ve had some bright red blood—was that from hemorrhoids?"
    },
    {
      "turn_number": 50,
      "time": "2156-09-02 10:02:00",
      "speaker": "Doctor",
      "text": "Yes, likely. Your hemoglobin is stable, so no concern now. Keep up the bowel regimen."
    },
    {
      "turn_number": 51,
      "time": "2156-09-02 10:03:00",
      "speaker": "Patient",
      "text": "And my sleep? I’ve been struggling."
    },
    {
      "turn_number": 52,
      "time": "2156-09-02 10:04:00",
      "speaker": "Doctor",
      "text": "We’re adding trazodone and adjusting Ambien. Also reducing zolpidem dose to avoid side effects."
    },
    {
      "turn_number": 53,
      "time": "2156-09-03 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re finalizing your discharge plan for tomorrow."
    },
    {
      "turn_number": 54,
      "time": "2156-09-03 08:01:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. What do I need to do?"
    },
    {
      "turn_number": 55,
      "time": "2156-09-03 08:02:00",
      "speaker": "Doctor",
      "text": "Continue tube feeds as tolerated. Take your new insulin dose—34 units at night. Use Dilaudid for pain as needed."
    },
    {
      "turn_number": 56,
      "time": "2156-09-03 08:03:00",
      "speaker": "Patient",
      "text": "And the bowel meds?"
    },
    {
      "turn_number": 57,
      "time": "2156-09-03 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, all of them—lactulose, senna, docusate, bisacodyl. They’ll help prevent constipation."
    },
    {
      "turn_number": 58,
      "time": "2156-09-03 08:05:00",
      "speaker": "Patient",
      "text": "I’ll follow up with my PCP for the MRI and vaginal check?"
    },
    {
      "turn_number": 59,
      "time": "2156-09-03 08:06:00",
      "speaker": "Doctor",
      "text": "Exactly. And call if your blood sugar goes too high or low, or if you can’t tolerate feeds."
    },
    {
      "turn_number": 60,
      "time": "2156-09-04 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. You’re alert, walking independently, and your labs are stable."
    },
    {
      "turn_number": 61,
      "time": "2156-09-04 09:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better than when I came in."
    },
    {
      "turn_number": 62,
      "time": "2156-09-04 09:02:00",
      "speaker": "Doctor",
      "text": "You’ve made great progress. Keep up with your follow-ups and medications."
    },
    {
      "turn_number": 63,
      "time": "2156-09-04 09:03:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    },
    {
      "turn_number": 64,
      "time": "2156-09-04 09:04:00",
      "speaker": "Doctor",
      "text": "Take care. We’ll see you in the clinic if needed."
    },
    {
      "turn_number": 65,
      "time": "2156-09-04 09:05:00",
      "speaker": "Patient",
      "text": "One last thing—my asthma. I’ve been using my inhalers."
    },
    {
      "turn_number": 66,
      "time": "2156-09-04 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, continue Advair and albuterol as prescribed. No changes there."
    },
    {
      "turn_number": 67,
      "time": "2156-09-04 09:07:00",
      "speaker": "Patient",
      "text": "Good. I almost forgot."
    },
    {
      "turn_number": 68,
      "time": "2156-09-04 09:08:00",
      "speaker": "Doctor",
      "text": "All set. Discharge papers are ready. Nurse will go over them with you."
    },
    {
      "turn_number": 69,
      "time": "2156-09-04 09:09:00",
      "speaker": "Patient",
      "text": "Okay, I’ll review them carefully."
    },
    {
      "turn_number": 70,
      "time": "2156-09-04 09:10:00",
      "speaker": "Doctor",
      "text": "Let us know if you have any questions after you get home."
    },
    {
      "turn_number": 71,
      "time": "2156-09-04 09:11:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 72,
      "time": "2156-09-04 09:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take it easy and rest."
    },
    {
      "turn_number": 73,
      "time": "2156-09-04 09:13:00",
      "speaker": "Patient",
      "text": "I plan to."
    },
    {
      "turn_number": 74,
      "time": "2156-09-04 09:14:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 75,
      "time": "2156-09-04 09:15:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 76,
      "time": "2156-09-04 09:16:00",
      "speaker": "Doctor",
      "text": "We’ll follow up with your PCP to coordinate care."
    },
    {
      "turn_number": 77,
      "time": "2156-09-04 09:17:00",
      "speaker": "Patient",
      "text": "That’s reassuring."
    },
    {
      "turn_number": 78,
      "time": "2156-09-04 09:18:00",
      "speaker": "Doctor",
      "text": "We want to make sure you stay stable."
    },
    {
      "turn_number": 79,
      "time": "2156-09-04 09:19:00",
      "speaker": "Patient",
      "text": "I appreciate that."
    },
    {
      "turn_number": 80,
      "time": "2156-09-04 09:20:00",
      "speaker": "Doctor",
      "text": "Take care of yourself."
    },
    {
      "turn_number": 81,
      "time": "2156-09-04 09:21:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 82,
      "time": "2156-09-04 09:22:00",
      "speaker": "Doctor",
      "text": "Goodbye for now."
    },
    {
      "turn_number": 83,
      "time": "2156-09-04 09:23:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 84,
      "time": "2156-09-04 09:24:00",
      "speaker": "Doctor",
      "text": "Nurse will assist you with discharge."
    },
    {
      "turn_number": 85,
      "time": "2156-09-04 09:25:00",
      "speaker": "Patient",
      "text": "Okay, I’m ready."
    }
  ],
  "summary": {
    "admission_start": "2156-07-30 17:07:00",
    "admission_end": "2156-09-04 16:03:00",
    "summary_paragraph": "The patient was admitted with inability to tolerate oral intake, worsening diarrhea, abdominal pain, and hyperglycemia following a trip where she consumed seafood. Initial management included bowel rest, IV fluids, and insulin for a glucose of 497. Stool studies were negative for infectious causes. Chronic pancreatitis and gastroparesis were deemed the likely contributors to her symptoms. Tube feeds were restarted but frequently interrupted due to pain. A GJ tube revision was performed successfully, after which feeds were better tolerated. Her insulin regimen was adjusted, with glargine increased to 34 units nightly. She fell during the stay, resulting in a wrist sprain and suspected rotator cuff injury, managed conservatively. Constipation from narcotics was treated with an aggressive bowel regimen. Despite reporting minimal intake, she gained weight with stable albumin, supporting discharge. She was transitioned from IV to oral pain medication and discharged home in stable condition with follow-up plans for MRI, gynecologic evaluation, and primary care.",
    "problems": [
      "Chronic pancreatitis",
      "Gastroparesis",
      "Diabetes with neurological manifestations, type I [juvenile type], uncontrolled",
      "Diarrhea",
      "Constipation, unspecified",
      "Sprain of wrist, unspecified site",
      "Fall from other slipping, tripping, or stumbling",
      "Borderline personality disorder",
      "Depressive disorder, not elsewhere classified",
      "Disorders of magnesium metabolism",
      "Other gastrostomy complications"
    ]
  }
}
